    drilling:{enabled:false,orientation:'axial',diameter:'',depth:'',peckDepth:'3',retractZ:'3',chipClearance:'0.5',tipAngle:'118',rpm:'800',feedRate:'80',toolId:'T5'},
    millingAf:{enabled:false,widthAcrossFlats:'',sides:'6',length:'',zStart:'',zEnd:'',toolDiameter:'8',radialStepDown:'1',axialLead:'1.5',radialClearance:'2',cOffset:'0',rpm:'2200',feedRate:'240',toolId:'T4'}
