async function downloadOperatorPdf(){if(!state.finalResult)return alert('Сначала зафиксируйте итоговый результат');const status=$('#pdfStatus'),button=document.querySelector('[data-type="pdf"]');if(button)button.disabled=true;if(status){status.className='check-card';status.textContent='Формирование PDF-карты оператора…'}try{const r=await fetch('/api/export/operator-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:state.finalResult})});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.detail||'Не удалось сформировать PDF')}const blob=await r.blob(),name=(state.projectName||'project').replace(/[^a-zа-яё0-9_-]+/gi,'_')+'_SINUMERIK_828D.pdf';downloadBlob(name,blob);if(status){status.className='check-card good';status.textContent='PDF сформирован и сохранён. Используйте его как карту ввода данных у стойки.'}showToast('PDF-карта оператора готова')}catch(error){if(status){status.className='check-card warning';status.textContent=error.message}alert(error.message)}finally{if(button)button.disabled=false}}
function exportProject(type){if(type==='pdf')return downloadOperatorPdf();if(!state.finalResult)return alert('Сначала зафиксируйте итоговый результат');if(type==='sinumerik'){const plan=window.CNC_CAM_currentPlan?.()||window.CNC_CAM_API?.buildCamPlan(window.CNC_CAM_getInput());if(!plan?.releaseReady||plan.postprocessor?.status!=='GENERATED')return alert('MPF заблокирован: проверьте паспортные данные, коллизии, M-коды и маршрут.');return download(`${plan.postprocessor.programName}.MPF`,plan.postprocessor.text,'text/plain;charset=utf-8')}if(type==='gcode')return alert('Обобщённый ISO G-code не заявлен; доступен только валидированный SINUMERIK 828D MPF.');if(type==='json')download('project-final.json',JSON.stringify(state.finalResult,null,2),'application/json')}
