  document.getElementById('dtTranslateBtn').onclick=async()=>{const pages=parsePages(pagesInput.value);if(!pages.length)return alert('Введите страницы, например 13-18');if(pages.length>8)return alert('За один запрос можно перевести не более 8 страниц');const btn=document.getElementById('dtTranslateBtn');btn.disabled=true;btn.textContent='ПЕРЕВОД…';try{const r=await fetch('/api/digital-twin/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({manual_id:translateManual.value,pages})}),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка перевода');alert(`Переведено/загружено из кэша: ${j.count} стр.`);btn.textContent='ГОТОВО'}catch(e){alert(e.message);btn.textContent='ПЕРЕВЕСТИ'}finally{btn.disabled=false}};
